class Solution:
    def build_and_query(self, nums: list[int], queries: list[tuple]) -> list[int]:
        n = len(nums)
        LOG = max(1, n.bit_length())
        st = [[0]*n for _ in range(LOG)]
        st[0] = nums[:]
        j = 1
        while (1 << j) <= n:
            i = 0
            while i + (1 << j) <= n:
                st[j][i] = min(st[j-1][i], st[j-1][i + (1 << (j-1))])
                i += 1
            j += 1

        def query(l, r):
            length = r - l + 1
            k = length.bit_length() - 1
            return min(st[k][l], st[k][r - (1 << k) + 1])

        return [query(l, r) for (l, r) in queries]

