from functools import lru_cache

class Solution:
    def count_with_digit_sum(self, n: int, k: int) -> int:
        digits = list(map(int, str(n)))

        @lru_cache(maxsize=None)
        def dp(pos, tight, total):
            if total > k:
                return 0
            if pos == len(digits):
                return 1 if total == k else 0
            limit = digits[pos] if tight else 9
            count = 0
            for d in range(0, limit+1):
                count += dp(pos+1, tight and d == limit, total+d)
            return count

        result = dp(0, True, 0)
        dp.cache_clear()
        return result

