class Solution:
    def min_path_cost(self, dist: list[list[int]]) -> int:
        n = len(dist)
        FULL = 1 << n
        INF = float('inf')
        dp = [[INF]*n for _ in range(FULL)]
        dp[1][0] = 0
        for mask in range(FULL):
            for u in range(n):
                if dp[mask][u] == INF or not (mask & (1 << u)):
                    continue
                for v in range(n):
                    if mask & (1 << v):
                        continue
                    new_mask = mask | (1 << v)
                    new_cost = dp[mask][u] + dist[u][v]
                    if new_cost < dp[new_mask][v]:
                        dp[new_mask][v] = new_cost
        return min(dp[FULL-1][u] for u in range(n))

