class Solution:
    def n_choose_r_mod(self, n: int, r: int, mod: int) -> int:
        if r < 0 or r > n:
            return 0
        fact = [1]*(n+1)
        for i in range(1, n+1):
            fact[i] = fact[i-1]*i % mod

        def mod_pow(a, b, m):
            result = 1
            a %= m
            while b:
                if b & 1:
                    result = result*a % m
                a = a*a % m
                b >>= 1
            return result

        def mod_inv(a, m):
            return mod_pow(a, m-2, m)

        return fact[n] * mod_inv(fact[r], mod) % mod * mod_inv(fact[n-r], mod) % mod

