    def kth_ancestors(self, parent: list[int], queries: list[tuple]) -> list[int]:
        n = len(parent)
        LOG = max(1, n.bit_length())
        up = [[-1]*n for _ in range(LOG)]
        up[0] = parent[:]
        for j in range(1, LOG):
            for v in range(n):
                if up[j-1][v] == -1:
                    up[j][v] = -1
                else:
                    up[j][v] = up[j-1][up[j-1][v]]

        def kth_ancestor(node, k):
            for j in range(LOG):
                if k & (1 << j):
                    node = up[j][node]
                    if node == -1:
                        return -1
            return node

        return [kth_ancestor(node, k) for node, k in queries]

