class Solution:
    def can_reach_target(self, nums: list[int], target: int) -> bool:
        n = len(nums)
        half = n // 2
        first, second = nums[:half], nums[half:]

        def all_sums(arr):
            sums = {0}
            for x in arr:
                sums |= {s + x for s in sums}
            return sums

        left_sums = all_sums(first)
        right_sums = all_sums(second)
        for ls in left_sums:
            if (target - ls) in right_sums:
                return True
        return False

