class TrieNode:
    __slots__ = ['children']
    def __init__(self):
        self.children = [None, None]

class Solution:
    def max_xor_pair(self, nums: list[int]) -> int:
        BITS = 32
        root = TrieNode()

        def insert(num):
            node = root
            for i in range(BITS - 1, -1, -1):
                bit = (num >> i) & 1
                if node.children[bit] is None:
                    node.children[bit] = TrieNode()
                node = node.children[bit]

        def query(num):
            node = root
            xor_val = 0
            for i in range(BITS - 1, -1, -1):
                bit = (num >> i) & 1
                want = 1 - bit
                if node.children[want] is not None:
                    xor_val |= (1 << i)
                    node = node.children[want]
                else:
                    node = node.children[bit]
            return xor_val

        insert(nums[0])
        best = 0
        for num in nums[1:]:
            best = max(best, query(num))
            insert(num)
        return best

