class Solution:
    def apply_updates(self, rows: int, cols: int, updates: list[tuple]) -> list[list[int]]:
        diff = [[0]*(cols+1) for _ in range(rows+1)]
        for (r1, c1, r2, c2, val) in updates:
            diff[r1][c1] += val
            diff[r1][c2+1] -= val
            diff[r2+1][c1] -= val
            diff[r2+1][c2+1] += val

        grid = [[0]*cols for _ in range(rows)]
        for r in range(rows):
            row_running = 0
            for c in range(cols):
                row_running += diff[r][c]
                grid[r][c] = row_running + (grid[r-1][c] if r > 0 else 0)
        return grid
